// YouTube reports embedding and availability errors through its player API.
(function () {
  const selector = 'iframe[src]';
  function isYouTube(frame) {
    const url = new URL(frame.src);
    return /(^|\.)youtube(?:-nocookie)?\.com$/.test(url.hostname) &&
      /^\/embed\/[\w-]{11}$/.test(url.pathname);
  }
  const frames = [...document.querySelectorAll(selector)].filter(isYouTube);
  if (!frames.length && !document.querySelector('.movie-poster')) return;

  function connectPlayers() {
    function connect(frame) {
      const url = new URL(frame.src);
      const id = url.pathname.split('/').pop();
      url.searchParams.set('enablejsapi', '1');
      url.searchParams.set('origin', window.location.origin);
      frame.src = url.href;
      new window.YT.Player(frame, {
        events: {
          onError(event) {
            if (!frame.isConnected) return;
            const panel = document.createElement('div');
            panel.className = 'video-fallback';
            const message = document.createElement('p');
            const embedBlocked = [101, 150, 153].includes(Number(event.data));
            message.textContent = embedBlocked
              ? 'This preview can be opened on YouTube.'
              : 'YouTube preview unavailable.';
            panel.append(message);
            if (embedBlocked || !frame.closest('.card')?.querySelector('a.download-btn:not([href*="youtube.com"])')) {
              const watch = document.createElement('a');
              watch.className = 'btn-secondary';
              watch.href = 'https://www.youtube.com/watch?v=' + id;
              watch.textContent = 'Open on YouTube';
              panel.append(watch);
            }
            frame.replaceWith(panel);
          }
        }
      });
    }

    if (!('IntersectionObserver' in window)) {
      frames.filter(frame => frame.isConnected).forEach(connect);
      return;
    }
    const observer = new IntersectionObserver(entries => {
      for (const { target, isIntersecting } of entries) {
        if (!isIntersecting || !target.isConnected) continue;
        observer.unobserve(target);
        connect(target);
      }
    }, { rootMargin: '250px' });
    const seen = new WeakSet();
    function observe(frame) {
      if (!seen.has(frame) && frame.isConnected && isYouTube(frame)) {
        seen.add(frame);
        observer.observe(frame);
      }
    }
    frames.forEach(observe);
    new MutationObserver(records => {
      for (const record of records) {
        for (const node of record.addedNodes) {
          if (node.nodeType !== 1) continue;
          if (node.matches(selector)) observe(node);
          node.querySelectorAll(selector).forEach(observe);
        }
      }
    }).observe(document.body, { childList: true, subtree: true });
  }

  if (window.YT?.Player) {
    connectPlayers();
    return;
  }
  const previous = window.onYouTubeIframeAPIReady;
  window.onYouTubeIframeAPIReady = function () {
    if (typeof previous === 'function') previous();
    connectPlayers();
  };
  const api = document.createElement('script');
  api.src = 'https://www.youtube.com/iframe_api';
  api.async = true;
  document.head.append(api);
})();
